namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public string ImagePlaceholder { get; set; } = "🍽️";
    public List<int> Ratings { get; set; } = new();
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = "";
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new();
    private int _nextId = 1;

    public RecipeService()
    {
        // Breakfast
        AddRecipe(new Recipe
        {
            Title = "Fluffy Pancakes",
            Category = "Breakfast",
            ImagePlaceholder = "🥞",
            Ingredients = new List<string> { "2 cups flour", "2 eggs", "1 cup milk", "2 tbsp sugar", "1 tbsp baking powder", "Pinch of salt", "Butter for cooking" },
            Steps = new List<string> { "Mix dry ingredients in a bowl.", "Whisk eggs and milk together.", "Combine wet and dry ingredients until just mixed.", "Heat a buttered pan over medium heat.", "Pour batter and cook until bubbles form, then flip.", "Serve with maple syrup." },
            Ratings = new List<int> { 5, 4, 5 }
        });
        AddRecipe(new Recipe
        {
            Title = "Avocado Toast",
            Category = "Breakfast",
            ImagePlaceholder = "🥑",
            Ingredients = new List<string> { "2 slices sourdough bread", "1 ripe avocado", "Salt and pepper", "Red pepper flakes", "Lemon juice", "1 egg (optional)" },
            Steps = new List<string> { "Toast the bread until golden.", "Mash avocado with lemon juice, salt, and pepper.", "Spread avocado on toast.", "Top with red pepper flakes and optional fried egg." },
            Ratings = new List<int> { 4, 5 }
        });

        // Lunch
        AddRecipe(new Recipe
        {
            Title = "Caesar Salad",
            Category = "Lunch",
            ImagePlaceholder = "🥗",
            Ingredients = new List<string> { "1 head romaine lettuce", "Caesar dressing", "Croutons", "Parmesan cheese", "Grilled chicken breast", "Lemon wedge" },
            Steps = new List<string> { "Chop romaine lettuce and place in a large bowl.", "Grill and slice chicken breast.", "Toss lettuce with Caesar dressing.", "Top with croutons, parmesan, and chicken.", "Squeeze lemon over the top and serve." },
            Ratings = new List<int> { 4, 4, 3 }
        });
        AddRecipe(new Recipe
        {
            Title = "Grilled Cheese Sandwich",
            Category = "Lunch",
            ImagePlaceholder = "🧀",
            Ingredients = new List<string> { "2 slices white bread", "2 slices cheddar cheese", "1 tbsp butter", "Tomato soup (for dipping)" },
            Steps = new List<string> { "Butter one side of each bread slice.", "Place cheese between the unbuttered sides.", "Cook in a skillet over medium heat until golden.", "Flip and cook the other side.", "Serve with tomato soup." },
            Ratings = new List<int> { 5, 5, 4 }
        });

        // Dinner
        AddRecipe(new Recipe
        {
            Title = "Spaghetti Bolognese",
            Category = "Dinner",
            ImagePlaceholder = "🍝",
            Ingredients = new List<string> { "400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste", "Salt, pepper, and Italian seasoning" },
            Steps = new List<string> { "Cook spaghetti according to package directions.", "Brown ground beef in a large pan.", "Add onion and garlic, cook until soft.", "Stir in crushed tomatoes and tomato paste.", "Season and simmer for 20 minutes.", "Serve sauce over spaghetti with parmesan." },
            Ratings = new List<int> { 5, 4, 5, 4 }
        });
        AddRecipe(new Recipe
        {
            Title = "Chicken Stir-Fry",
            Category = "Dinner",
