                    </p>
                </div>
            </div>

            <h3 class="mt-4">Ingredients</h3>
            <ul class="list-group list-group-flush mb-4">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>

            <h3>Steps</h3>
            <ol class="list-group list-group-numbered list-group-flush mb-4">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>

        <div class="col-md-4">
            <div class="card shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">Rate this Recipe</h5>
                    <StarRating RecipeId="@Id" @rendermode="InteractiveServer" />
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }

    private string GetStarDisplay(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@rendermode InteractiveServer
@inject RecipeService RecipeService

<div>
    <div style="font-size: 2rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span style="color: gold;" @onclick="() => Rate(star)">
                @(star <= currentHover ? "★" : "☆")
            </span>
        }
    </div>

    @if (submitted)
    {
        <p class="text-success mt-2">Thanks for rating!</p>
    }

    <p class="mt-2 text-muted">
        Average: @averageRating.ToString("0.0") / 5
        (@ratingCount ratings)
    </p>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int currentHover;
    private bool submitted;
    private double averageRating;
    private int ratingCount;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
        currentHover = stars;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            averageRating = recipe.AverageRating;
            ratingCount = recipe.Ratings.Count;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1 class="mb-4">Submit a Recipe</h1>

@if (submittedRecipeId is not null)
{
    <div class="alert alert-success">
        <strong>Recipe submitted successfully!</strong>
        <a href="recipe/@submittedRecipeId">View your recipe</a>
    </div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.Category">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Lunch">Lunch</option>
            <option value="Dinner">Dinner</option>
            <option value="Desserts">Desserts</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="model.Steps" />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission model = new();
    private int? submittedRecipeId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        submittedRecipeId = recipe.Id;
        model = new();
    }
}

