@page "/"
@inject RecipeService RecipeService

<PageTitle>RecipeCommunity - Home</PageTitle>

<div class="text-center my-5">
    <h1 class="display-4">🍽️ Welcome to RecipeCommunity</h1>
    <p class="lead text-muted">Discover, share, and rate delicious recipes from our community.</p>
    <a href="submit" class="btn btn-primary btn-lg mt-3">Submit a Recipe</a>
</div>

<h2 class="mb-4">Browse by Category</h2>
<div class="row">
    @foreach (var category in categories)
    {
        var recipes = RecipeService.GetByCategory(category);
        var emoji = recipes.FirstOrDefault()?.ImagePlaceholder ?? "🍽️";
        <div class="col-md-3 col-sm-6 mb-4">
