                        <p class="text-muted">@recipes.Count recipes</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

@code {
    private List<string> categories = new();

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }
}

